-- Iteration timeline schema + seed (see https://github.com/cyrilleulmi/spongecoach/issues/12).
-- Adds the team-overview timeline surface: Iterations group Events (Training/Match), both
-- ordered by a plain integer position (ADR-0007), and a three-way Line-Focus-Event link
-- records which Focus a Line has set for a given Event (one Focus per Line per Event).
--
-- Fixed UUIDs by kind, continuing V3's scheme: 6=iteration, 7=event, 8=event_type.
-- Seed content is German (the team's language); domain terms stay English per docs/glossary.md.

create table event_type (
    id uuid primary key,
    name varchar(50) not null
);

create table iteration (
    id uuid primary key,
    team_id uuid not null references team (id),
    name varchar(100) not null,
    position int not null
);

create table event (
    id uuid primary key,
    iteration_id uuid not null references iteration (id),
    event_type_id uuid not null references event_type (id),
    -- Trainings are numbered by position, not named, so name is null for them;
    -- Matches carry the opponent as their name.
    name varchar(100),
    position int not null,
    scheduled_on date
);

create index idx_event_iteration on event (iteration_id);

-- Which Focus a Line has set for an Event. Payload-carrying join (like line_skill),
-- so it's a real table, not a plain n:n: at most one Focus per (Event, Line).
create table line_focus_event (
    event_id uuid not null references event (id),
    line_id uuid not null references line (id),
    focus_id uuid not null references focus (id),
    primary key (event_id, line_id)
);

-- Event types: seeded with the two the domain knows, but an open list (ADR-0006 pattern).
